"""Freeze the patient selection and contracts before numerical execution."""
from dental_release.paths import expand as _release_expand
import datetime, hashlib, json
from pathlib import Path
R = Path(__file__).resolve().parent
D = R.parent.parent
P = D / 'results/DEMO48_PACKAGE'
DATA = Path(_release_expand('@DENTAL_WORK_ROOT@/X70_end_to_end'))

def sha(p):
    return hashlib.sha256(Path(p).read_bytes()).hexdigest()

def write(p, x):
    Path(p).write_text(json.dumps(x, indent=2, ensure_ascii=False) + '\n')

def freeze(p, x):
    if p.exists():
        raise RuntimeError('Already frozen: ' + str(p))
    write(p, x)
    p.with_name(p.name + '.sha256').write_text(sha(p) + '\n')
cohort = json.loads((P / 'batch10/demos/GENCAD_V4/payload/private/COHORT.json').read_text())
bits = sorted([r for r in cohort if r['dataset'] == 'Bits2Bites'], key=lambda r: r['case_key'])
row = bits[0]
freeze(R / 'PATIENT_SELECTION.json', dict(selection='First Bits2Bites case by lexicographic case_key in frozen v4 auxiliary cohort; no output-based selection', patient=row, requested_family='molar_crown', level='normal', cohort_bits_count=len(bits), not_selected=len(bits) - 1, no_outcome_rejections_before_selection=True))
timestamp = datetime.datetime.now(datetime.timezone.utc).isoformat()
freeze(R / 'PREREG_X70_R1.json', dict(lane='X70-end-to-end', round='R1', frozen_utc=timestamp, claim_type='capability', capability='One local command carries one registered Bits2Bites patient through the available digital preparation/generation, design, milling, source-calibration support, 3MF, metrology and prospective lab handover', obstacle='Separately demonstrated modules have different patient/frame/region/protocol contracts; no paired manufactured crown, seated film or fracture outcome exists for this patient', changed_operation='Executable composition with shared patient frame, per-facet regions, source hashes, immutable scientific artifacts and explicit unsupported physical ports. Invoke reviewed packaged operations without changing them.', consumer='Prosthodontics researcher with CAD/CAM and laboratory measurements; no clinical release', generator_selection='PROOF_LANE_FULL_CROWN was an empty directory at selection; fallback packaged X60 roof optimizer, explicitly restricted occlusal specimen, complete axial crown UNKNOWN', measures=[dict(name='same_patient_and_mesh_binding', tolerance=0, unit='hash mismatches', decision='PASS only if every geometry consumer binds the exact generated STL and declared frame'), dict(name='rerun_scientific_bytes', tolerance=0, unit='differing bytes', decision='PASS only if all declared scientific artifacts match in two fresh runs; runtime telemetry excluded explicitly before run'), dict(name='source_force_interiors', tolerance=0.2, unit='absolute log ratio', decision='Compare all existing eligible held interior thickness groups to frozen endpoint interpolation; preserve each failure'), dict(name='source_dry_gap', tolerance=20, unit='um', decision='Use frozen v4 source predictions and primary regional group means; never transfer them as individual seated film'), dict(name='3MF_roundtrip', tolerance=1e-06, unit='mm', decision='Geometry, labels, units and bound gate must survive published trimesh importer and X49 native metadata check'), dict(name='exact_summary_sufficiency', tolerance=0, unit='summary identity error', decision='Two exactly identical summaries tested by existing X60 mechanics; keep local support/load/thickness if downstream response differs'), dict(name='reject_injected_faults', tolerance=0, unit='false acceptances', decision='Wrong input hash, units, translated crown, missing calibration, metrology region hash, external target force and X61 patient identity must reject')], strongest_equal_information_control='Original GenCAD all_checks, naive published nearest triangle distances, independently reloaded 3MF and source endpoint interpolation. Capability verification, no algorithm superiority claim.', falsifier='Cross-patient or frame mismatch, changed source, any unsupported physical port labelled calibrated, any admitted injected identity fault, scientific byte drift or absent requested stage', full_capability_gate='All digital stages execute AND complete axial anatomy, physically calibrated generated fracture force, physical seated film and matched actual measurement are supported. Otherwise PARTIAL; never upgrade UNKNOWN.', external_referent=dict(kind='published_dataset', locator='https://ditto.ing.unimore.it/bits2bites/ ; local Bits2Bites_v01.zip members named in SCAN.json', compared_quantity='Registered upper/lower measured scan surface coordinates, not anatomical segmentation or crown physical response', refutes_us=True), other_external_referents=[dict(kind='independent_measurement', locator='doi:10.4047/jap.2021.13.5.269 Table1; doi:10.3390/ma17020365 Table2', compared_quantity='Published protocol-specific crown failure forces in N', refutes_us=True), dict(kind='independent_measurement', locator='doi:10.7759/cureus.38688 Table2; doi:10.1155/2023/6698453 Table1', compared_quantity='Dry marginal group gap in um, distinct from seated cement film', refutes_us=True)], resolution='PER_POINT and PER_SURFACE_REGION ports; consumer aggregates to PER_TOOTH; source group data POPULATION', timescale='SIMULTANEOUS geometry and numerical checks; HANDOVER manufacture -> metrology -> subsequent model update', cost=dict(preparation='Directed existing-source and license read/hash; wall time UNKNOWN', fit='No new model or segmentation fit; original fit/inference costs UNKNOWN', discovery='One deterministic patient/task; all rejected gates retained', validation='Two fresh numerical runs plus source held outcomes, fault controls and export importer', questions=0, fallback='No supported absolute transfer: immutable lab protocol with required measurements; physical acquisition cost UNKNOWN'), resources=dict(threads_max=4, own_bytes_max=3000000000, GPU=False, expected_RSS_below_4GB=True, heavy_if_needed=str(D / 'tasks/heavy_run.sh'))))
freeze(R / 'DECOMPOSITION.json', dict(idea='A laboratory can trace every predicted and measured quantity back to the same digital specimen.', mechanism='Composition preserves spatial fields, patient transforms, material/protocol identity and unknown leaves across modules.', equation='x_local=(x_scan-base) R; phi(x)=signed distance to declared capped roof; F(u,x,theta)=0 uses existing X60 elastic closure; g(x)<=0 uses unchanged digital checks; y_lab=H(x,theta)+error requires same specimen/protocol.', operation='Extract only two existing archive members; read frozen segmentation; rebuild site; sample SDF; virtual preparation; existing generator; gate; pointwise tools; support test; export; metrology; lab admission.', representation='Common mm frame and per-point/per-facet spatial ports with shared SHA256 provenance. No fusion of source population means into patient point measurements.', leaves=[dict(name='registered IOS coordinates', status='EXTERNALLY_MEASURED', locator='https://ditto.ing.unimore.it/bits2bites/', stopping_argument='Raw measured surfaces available; independent scanner accuracy and bite-pose uncertainty absent.'), dict(name='X11 tooth labels and dental frame', status='CONSTITUTIVE_CLOSURE', stopping_argument='Frozen model predictions in X11; no expert PER_POINT labels for this case. Do not report segmentation accuracy.'), dict(name='local coordinate transform and facet ownership', status='DERIVED_UNDER_ASSUMPTIONS', stopping_argument='Rigid transform and original indexing exact up to floating arithmetic; inferred anatomical frame is not measured.'), dict(name='capped affine roof SDF and virtual preparation', status='CONSTITUTIVE_CLOSURE', stopping_argument='Existing representation omits axial anatomy, root/dentin and true preparation; signed volume requires explicit cap.'), dict(name='X60 material/support/load Weibull elasticity', status='CONSTITUTIVE_CLOSURE', stopping_argument='Unchanged parent model; constitutive constants and force scale not matched to generated patient specimen. No rigorous sensitivity enclosure.'), dict(name='source force and dry marginal gap', status='EXTERNALLY_MEASURED', stopping_argument='Primary published group endpoints; protocol and quantity prevent direct individual transfer.'), dict(name='physical generated force and seated film', status='UNKNOWN', stopping_argument='No manufactured matched specimen; no measurement can be fabricated in software.'), dict(name='whole tool envelope', status='CONSTITUTIVE_CLOSURE', stopping_argument='Published nominal tip reference converted by X53; actual holder, gauge and fixture remain unmeasured.'), dict(name='metrology rigid datum transform', status='DERIVED_UNDER_ASSUMPTIONS', stopping_argument='Published rigid least-squares geometry; actual datum and scanner uncertainty need acquisition.'), dict(name='same-patient lab alarm transfer', status='UNKNOWN', stopping_argument='X61 is trained/frozen on D1/M1/M2 and rejects this patient ID; requires new measured likelihood profile before posterior updates.')], assumption_debts=['No continuous floating-point geometry enclosure', 'No mesh-convergence enclosure', 'No rigorous affine design sensitivity enclosure', 'No clinical inference'], discriminating_test='Two fresh runs; exact-summary X60 counterexample; matched external held source targets; adversarial protocol/region/patient hash and value injections.'))
maps = {_release_expand('X49'): 'batch12/demos/X49', _release_expand('X53'): 'batch13/demos/X53', _release_expand('X55'): 'batch14/demos/X55', _release_expand('X60'): 'batch15/demos/X60', _release_expand('X61'): 'batch15/demos/X61', _release_expand('GENCAD_V4'): 'batch10/demos/GENCAD_V4', _release_expand('X1B'): 'demos/X1B'}
freeze(R / 'PACKAGE_MAP.json', dict(mounts={str(D / 'results' / k): str(P / v) for (k, v) in maps.items()}, policy='read-only entire filesystem, packaged modules mounted at original logical paths; only X70 lane and its data directory writable'))
files = []
for path in maps.values():
    p = P / path
    for q in sorted(p.glob('code/*.py')):
        files.append(dict(path=str(q), sha256=sha(q), bytes=q.stat().st_size))
for sub in ['payload/participant_code', 'payload/literature']:
    for q in sorted((P / 'batch10/demos/GENCAD_V4' / sub).rglob('*')):
        if q.is_file() and q.suffix in ('.py', '.json', '.csv'):
            files.append(dict(path=str(q), sha256=sha(q), bytes=q.stat().st_size))
for path in ['batch13/demos/X53/NOMINAL_TIP_REFERENCE_CARD.json', 'batch10/demos/GENCAD_V4/FROZEN_LITERATURE_PREDICTIONS.json', 'demos/X1B/raw/MATCHED_R2.json']:
    q = P / path
    files.append(dict(path=str(q), sha256=sha(q), bytes=q.stat().st_size))
for q in [Path(row['metadata']), Path(row['metadata']).parent / 'upper_labels.npz', Path(row['metadata']).parent / 'lower_labels.npz']:
    files.append(dict(path=str(q), sha256=sha(q), bytes=q.stat().st_size))
freeze(R / 'SOURCE_LOCK.json', dict(files=files, selection_sha256=sha(R / 'PATIENT_SELECTION.json'), archive_policy='Verify selected ZIP members; whole dataset zip is not copied/hashed. Local archive inventory needed.', timestamp_utc=timestamp))
DATA.mkdir(parents=True, exist_ok=True)
print(json.dumps(dict(patient_case=row['case'], case_key=row['case_key'], locked_files=len(files))))
